pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmt, uint256 collectAmt, address alice, address bob) public {
        vm.assume(alice != address(0) && bob != address(0) && alice != bob);
        depositAmt = bound(depositAmt, 1, 10 ether);
        collectAmt = bound(collectAmt, 1, 10 ether);
        // Initialize contract
        c.SetMinSum(0);
        c.Initialized();
        // Give Alice and Bob some Ether
        vm.deal(alice, 20 ether);
        vm.deal(bob, 20 ether);
        // Alice deposits
        vm.prank(alice);
        c.Deposit{value: depositAmt}();
        // Track Alice's balance externally
        uint256 aliceBalAfterDeposit = c.balances(alice);
        // Bob deposits a small amount so he exists
        vm.prank(bob);
        c.Deposit{value: 1 ether}();
        // Now Alice tries to collect part of her balance (or full)
        uint256 collectAmount = collectAmt > aliceBalAfterDeposit ? aliceBalAfterDeposit : collectAmt;
        uint256 aliceBalBeforeCollect = c.balances(alice);
        uint256 bobBalBeforeCollect = c.balances(bob);
        uint256 totalBalBeforeCollect = aliceBalBeforeCollect + bobBalBeforeCollect;
        vm.prank(alice);
        c.Collect(collectAmount);
        uint256 aliceBalAfterCollect = c.balances(alice);
        uint256 bobBalAfterCollect = c.balances(bob);
        uint256 totalBalAfterCollect = aliceBalAfterCollect + bobBalAfterCollect;
        // The total balance (Alice+Bob) should be >= previous total - collected amount (since internal accounting should match)
        // But due to the bug (subtraction on deposit), alice's balance is zeroed, breaking the relation.
        assertTrue(totalBalAfterCollect >= totalBalBeforeCollect - collectAmount);
    }
}

