pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmt, uint256 collectAmt, address caller, uint256 otherDeposit, address other) public {
        vm.assume(caller != address(0) && other != address(0) && caller != other);
        vm.assume(depositAmt > 0 && depositAmt < type(uint256).max / 2);
        vm.assume(collectAmt > 0 && collectAmt <= depositAmt);
        vm.assume(otherDeposit > 0 && otherDeposit < type(uint256).max / 2);

        // Initialize contract
        c.Initialized();
        c.SetMinSum(0);
        c.SetLogFile(address(new LogFileHelper()));

        // Record initial balance of caller
        uint256 initBal = c.balances(caller);

        // Caller deposits
        vm.deal(caller, depositAmt);
        vm.prank(caller);
        c.Deposit{value: depositAmt}();
        uint256 balAfterDeposit = c.balances(caller);

        // Another user deposits (should not affect caller's balance directly)
        vm.deal(other, otherDeposit);
        vm.prank(other);
        c.Deposit{value: otherDeposit}();

        // Caller collects up to deposit amount
        vm.prank(caller);
        c.Collect(collectAmt);
        uint256 balAfterCollect = c.balances(caller);

        // General invariant: caller's balance after collect equals initial + deposit - collect
        assertTrue(balAfterCollect == initBal + depositAmt - collectAmt);
    }
}

contract LogFileHelper {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

