contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 collectAmount, address collector) public {
        vm.assume(depositAmount > 0);
        vm.assume(collectAmount > 0);
        vm.assume(collectAmount <= depositAmount);
        vm.assume(collector != address(0));
        vm.assume(collector != address(this));
        vm.assume(collector != address(c));

        // Initialize contract
        c.SetMinSum(0);
        c.SetLogFile(address(new LogFile()));
        c.Initialized();

        // Deposit via receive()
        vm.deal(collector, depositAmount);
        vm.prank(collector);
        (bool depositOk,) = address(c).call{value: depositAmount}("");
        require(depositOk, "deposit failed");

        // Collect
        vm.prank(collector);
        try c.Collect(collectAmount) { } catch { }

        // After Collect, the collector's balance should be >= 0 (trivially true if deposit updated balances)
        // In the buggy version, balance is 0, but collect may succeed draining other balances; this is fine.
        // The actual invariant: if deposit didn't update, balance was 0, collectAmount > 0 would revert,
        // but we need a rule that holds for reference and fails for bug.
        // Better: After deposit and collect, the balance of collector must be depositAmount - collectAmount (if collect succeeded).
        // In buggy: balance remains 0, so if collect succeeded (which it can't if balance<collectAmount, but MinSum=0 allows collect from 0 balance? Yes, require(balances[sender]>=MinSum (0) && balances[sender]>=_am) would fail for _am>0 because balance=0. So collect would revert.
        // We need to drive Collect, so we need balance > 0 in reference. But buggy version never increments balance, so collect always reverts for _am>0. The difference: reference Collect succeeds, buggy Collect reverts.
        // So we check the success of Collect.
        // Actually, we can assert: after deposit, balance must be >= depositAmount. In reference: true; in buggy: false (balance is 0).
        // That's a direct view on public getter.
        assertTrue(c.balances(collector) >= depositAmount);
    }
}

