pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 depositAmount, uint256 collectAmount) public {
        // restrict to admissible domain: sender non-zero, depositAmount > 0, collectAmount <= depositAmount
        vm.assume(sender != address(0));
        vm.assume(depositAmount > 0);
        collectAmount = bound(collectAmount, 0, depositAmount);

        // initialize contract
        c.Initialized();

        // fund sender and deposit via receive()
        vm.deal(sender, depositAmount);
        vm.prank(sender);
        (bool sent,) = address(c).call{value: depositAmount}("");
        require(sent, "deposit failed");

        // collect exactly the balance the contract thinks it has after deposit
        vm.prank(sender);
        c.Collect(collectAmount);

        // after Collect that empties the balance, the contract's recorded balance must be exactly 0
        // if depositAmount == collectAmount and deposit was recorded, balance becomes 0.
        // In buggy version, balance remains 0 always, so collect reverts or does nothing.
        // The invariant: recorded balance of sender is 0 if full amount collected (collectAmount == depositAmount),
        // but bug fails to update balance so it stays 0 even without collect, making Collect revert for any amount > 0.
        // We assert: after the Collect, the sender's recorded balance equals (depositAmount - collectAmount)
        // which is the correct behavior, and buggy version breaks for collectAmount > 0.
        assertEq(c.balances(sender), depositAmount - collectAmount);
    }
}

